{
  "units": [
    {
      "quote": "8 FAM 403.1-4 Material Discrepancies (Major name changes)",
      "meaning": "Provides the section title establishing the subject as material discrepancies and major name changes; contains no independent operational requirement or rule.",
      "kind": "background",
      "scope_quotes": []
    },
    {
      "quote": "(CT:CITZ-141; 03-10-2026)",
      "meaning": "Provides administrative version and revision date metadata without substantive legal or procedural obligation.",
      "kind": "background",
      "scope_quotes": []
    },
    {
      "quote": "A material discrepancy is any name change that is not defined as immaterial in 8 FAM 403.1-5.",
      "meaning": "Defines a material discrepancy as any name change that does not qualify as immaterial under 8 FAM 403.1-5.",
      "kind": "definition",
      "scope_quotes": ["a."]
    },
    {
      "quote": "The applicant must explain any material discrepancies between the name on the application and the name recorded in the evidence of U.S. citizenship/non-citizen U.S. nationality and the evidence of identity (see 22 CFR 51.25).",
      "meaning": "Applicants are required to provide an explanation for any material discrepancies between their application name, citizenship/nationality evidence name, and identity evidence name.",
      "kind": "requirement",
      "scope_quotes": ["a."]
    },
    {
      "quote": "Material discrepancies between the name recorded on the application, the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality, or the evidence of identity must be documented by submission of one or more of the documents listed in this section",
      "meaning": "Applicants must document material discrepancies among the application name, citizenship/nationality evidence, or identity evidence by submitting at least one acceptable document specified in the section.",
      "kind": "requirement",
      "scope_quotes": ["b."]
    },
    {
      "quote": "see an exception for married names in 8 FAM 403.1-4(C)",
      "meaning": "Directs to an exception from the material discrepancy documentation rules for married names set forth in 8 FAM 403.1-4(C).",
      "kind": "exception",
      "scope_quotes": [
        "b. Material discrepancies between the name recorded on the application, the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality, or the evidence of identity must be documented by submission of one or more of the documents listed in this section"
      ]
    },
    {
      "quote": "Court orders or decrees:",
      "meaning": "Identifies court orders or decrees as an acceptable category of documentation for establishing a material name change.",
      "kind": "alternative",
      "scope_quotes": [
        "b.",
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ]
    },
    {
      "quote": "Name change orders;",
      "meaning": "Specifies name change orders as an acceptable type of court order or decree for documenting a material name change.",
      "kind": "alternative",
      "scope_quotes": [
        "b.",
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):",
        "(1) Court orders or decrees:"
      ]
    },
    {
      "quote": "Divorce decrees;",
      "meaning": "Specifies divorce decrees as an acceptable type of court order or decree for documenting a material name change.",
      "kind": "alternative",
      "scope_quotes": [
        "b.",
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):",
        "(1) Court orders or decrees:"
      ]
    },
    {
      "quote": "(2) Certificates of naturalization;",
      "meaning": "Identifies certificates of naturalization as an acceptable category of documentation to establish a material name change.",
      "kind": "alternative",
      "scope_quotes": [
        "b.",
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ]
    },
    {
      "quote": "(3) Marriage certificates;",
      "meaning": "Identifies marriage certificates as an acceptable category of documentation to establish a material name change.",
      "kind": "alternative",
      "scope_quotes": [
        "b.",
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ]
    },
    {
      "quote": "(4) Documentation demonstrating change of name by operation of state law; or",
      "meaning": "Identifies documentation demonstrating a name change occurred by operation of state law as an acceptable means of documenting a material name change.",
      "kind": "alternative",
      "scope_quotes": [
        "b.",
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ]
    },
    {
      "quote": "(5) Documentation of customary usage.",
      "meaning": "Identifies documentation of customary usage as an acceptable means of documenting a material name change.",
      "kind": "alternative",
      "scope_quotes": [
        "b.",
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ]
    },
    {
      "quote": "NOTE: Evidence of material name changes must be reviewed for evidence of counterfeiting or alteration (see 8 FAM 201.1)",
      "meaning": "Passport personnel must examine all evidence submitted for material name changes to check for counterfeiting or alteration.",
      "kind": "requirement",
      "scope_quotes": []
    },
    {
      "quote": "The applicant may not continue to use a previous name after a material name change",
      "meaning": "Applicants are prohibited from continuing to use a former name once a material name change has occurred.",
      "kind": "prohibition",
      "scope_quotes": ["c."]
    },
    {
      "quote": "unless the name change documentation specifically permits the applicant to continue using that name (see 8 FAM 403.1-6 regarding “known as” names).",
      "meaning": "Permits an applicant to continue using a previous name after a material name change if the documentation of the name change explicitly authorizes continued use.",
      "kind": "exception",
      "scope_quotes": [
        "c.",
        "The applicant may not continue to use a previous name after a material name change"
      ]
    },
    {
      "quote": "The applicant's name is an integral part of her/his identity.",
      "meaning": "Articulates the foundational principle that an individual's name is an essential component of identity; contains no independent mandate.",
      "kind": "statement",
      "scope_quotes": ["d."]
    },
    {
      "quote": "Consequently, under 22 CFR 51.23(c), evidence of identity might be required in accordance with Department guidance to establish the name that best identifies the applicant:",
      "meaning": "States that Department guidance may require identity evidence under 22 CFR 51.23(c) to confirm which name best identifies the applicant.",
      "kind": "statement",
      "scope_quotes": ["d."]
    },
    {
      "quote": "more than one year prior to applying on form DS-11",
      "meaning": "Establishes a timing threshold of greater than one year between the occurrence of a material name change and submission of a Form DS-11 application.",
      "kind": "threshold",
      "scope_quotes": [
        "d.",
        "(1) If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change, you must suspend the application to request an acceptable ID in the new name."
      ]
    },
    {
      "quote": "If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change, you must suspend the application to request an acceptable ID in the new name.",
      "meaning": "Adjudicators are required to suspend the application and request acceptable ID reflecting the new name if the applicant's material name change took place over a year before filing Form DS-11 and their ID has not been updated.",
      "kind": "requirement",
      "scope_quotes": ["d."]
    },
    {
      "quote": "If there is insufficient time to request that the applicant submit acceptable ID prior to urgent or emergency travel, a limited-validity passport may be issued in the requested name;",
      "meaning": "Allows issuance of a limited-validity passport in the requested name when urgent or emergency travel leaves inadequate time to obtain acceptable updated ID.",
      "kind": "permission",
      "scope_quotes": [
        "d.",
        "(1) If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change, you must suspend the application to request an acceptable ID in the new name."
      ]
    },
    {
      "quote": "The applicant generally will need the name change documentation to change the name on her/his ID.",
      "meaning": "States the general expectation that an applicant requires their name change documentation in order to update the name on their identification.",
      "kind": "statement",
      "scope_quotes": ["d.", "(2)"]
    },
    {
      "quote": "You must fully notate the name change documentation prior to returning the documentation, including that the documentation was \"seen and returned,\" to the applicant with the information request letter (IRL); and",
      "meaning": "Mandates that adjudicators thoroughly notate name change documentation, specifically recording that it was 'seen and returned,' before sending it back with an Information Request Letter (IRL).",
      "kind": "requirement",
      "scope_quotes": ["d."]
    },
    {
      "quote": "within one year of applying on a form DS-11",
      "meaning": "Defines a temporal window of one year or less between a material name change and application on Form DS-11.",
      "kind": "threshold",
      "scope_quotes": [
        "d.",
        "(3) Applicants who have had a material name change within one year of applying on a form DS-11 do not need to submit ID in the new name."
      ]
    },
    {
      "quote": "Applicants who have had a material name change within one year of applying on a form DS-11 do not need to submit ID in the new name.",
      "meaning": "Exempts applicants from having to provide identification in their new name if their material name change occurred within one year of applying on Form DS-11.",
      "kind": "exemption",
      "scope_quotes": ["d."]
    },
    {
      "quote": "However, if the ID has not yet been changed, they must submit their name change documentation.",
      "meaning": "Requires applicants whose name change occurred within one year of applying to submit their name change documentation if their ID has not yet been updated.",
      "kind": "requirement",
      "scope_quotes": [
        "d.",
        "(3) Applicants who have had a material name change within one year of applying on a form DS-11 do not need to submit ID in the new name."
      ]
    }
  ]
}
